// Writes src/c/words.rs: the words that the big alternations of the `c`
// grammar spell out, expanded and sorted, so a matcher can test a whole word
// against a list.
//
// Run with `bun run oracle/c-words.ts`, then `cargo +nightly-2026-11-01 fmt
// --all`, and commit the result; the output is generated, do not edit it.
import c from "@shikijs/langs@4.6.0/c";

type Node = { match?: string; begin?: string; patterns?: Node[] };
const repository = (c as unknown as { repository: Record<string, Node> }[])[0]!.repository;

/** The regex of the `index`th pattern of repository entry `key`, or of the entry itself. */
function regexOf(key: string, index?: number): string {
  const node = index === undefined ? repository[key]! : repository[key]!.patterns![index]!;
  return (node.match ?? node.begin)!;
}

/** The capture of `pattern` in `regex`, split at its alternation bars. */
function alternatives(pattern: RegExp, regex: string): string[] {
  const m = pattern.exec(regex);
  if (!m) throw new Error(`${pattern} does not match ${regex}`);
  return m[1]!.split("|");
}

/** Expands the one `[cr]?iterate` and `FMAF??` shorthand the lists use. */
const expand = (w: string): string[] =>
  w === "[cr]?iterate"
    ? ["iterate", "citerate", "riterate"]
    : w === "__FP_FAST_FMAF??"
      ? ["__FP_FAST_FMA", "__FP_FAST_FMAF"]
      : [w];

const plain = /^\\b\((.*)\)\\b$/;
const storage = /\(\?:(.*)\)\(\?!\\w\)\)$/;
const exclusion = /^\(\?!\(\?:(.*?)\)\\s\*\\\(\)/;

const lists: Record<string, string[]> = {
  CONTROL: alternatives(plain, regexOf("anon_pattern_1")),
  MODIFIER: alternatives(plain, regexOf("anon_pattern_3")),
  CONSTANT: alternatives(plain, regexOf("anon_pattern_7")),
  SYS_TYPES: alternatives(plain, regexOf("anon_pattern_8")),
  MAC_CONSTANT: alternatives(plain, regexOf("anon_pattern_11")),
  MAC_TYPE: alternatives(plain, regexOf("anon_pattern_12")),
  PRIMITIVE: alternatives(storage, regexOf("storage_types", 0)),
  BUILTIN: alternatives(storage, regexOf("storage_types", 1)),
  STDINT: alternatives(/^\\b\(\(\?:(.*)\)_t\)\\b$/, regexOf("anon_pattern_10")).map((w) => `${w}_t`),
  PTHREAD: [
    "pthread_t",
    ...alternatives(/^\\b\(pthread_\(\?:(.*)\)t\)\\b$/, regexOf("anon_pattern_9"))
      .filter((w) => w)
      .map((w) => `pthread_${w}t`),
  ],
  PREDEF: alternatives(plain, regexOf("predefined_macros", 0)).flatMap(expand),
  FUNCDEF_EXCL: alternatives(
    /^\(\?<!\\w\)\(\?!\\s\*\(\?:(.*?)\)\\s\*\\\(\)/,
    regexOf("anon_pattern_range_7"),
  ),
  MEMBER_EXCL: alternatives(/\(\?!\(\?:(.*)\)\\b\)\[A-Z_a-z\]/, regexOf("member_access")),
  CALL_EXCL: alternatives(exclusion, regexOf("c_function_call")).flatMap(expand),
  DEFINE_EXCL: alternatives(
    exclusion,
    regexOf("preprocessor-rule-define-line-contents", 4),
  ).flatMap(expand),
};

let out = `//! The words the grammar's alternations spell out, sorted. Generated by
//! \`oracle/c-words.ts\`; do not edit.

`;
for (const [name, list] of Object.entries(lists)) {
  const sorted = [...new Set(list)].sort();
  out += `pub(super) const ${name}: &[&str] = &[\n${sorted.map((w) => `    "${w}",\n`).join("")}];\n\n`;
}
out += `/// Whether \`word\` is in the sorted \`list\`.
pub(super) fn has(list: &[&str], word: &[u8]) -> bool {
    list.binary_search_by(|probe| probe.as_bytes().cmp(word)).is_ok()
}
`;
await Bun.write(new URL("../src/c/words.rs", import.meta.url).pathname, out);
